package net.civeira.phylax.features.access.usergroupmembership.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class GroupsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property groups of user group membership ")
  void test_groups_v_o_builder() {
    Assertions.assertFalse(GroupsVO.nullValue().getGroups().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(GroupsVO.tryFrom(null).getGroups().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", GroupsVO.from("one").getGroups().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> GroupsVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", GroupsVO.from("one").toString());
  }
}
